package com.vandorlabs.neoforge.screen;
import com.google.gson.*;
import com.vandorlabs.neoforge.*;
/** Actual source-exported policy is fixture input, not a production resource binding. */
final class ScreenFixtureCatalog implements NativeScreenEntity.Catalog {
 private final JsonObject source,pairs;private final JsonArray choices;private final java.util.Set<String> framed=new java.util.HashSet<>(),inputs=new java.util.HashSet<>();
 ScreenFixtureCatalog(){try(var reader=java.nio.file.Files.newBufferedReader(java.nio.file.Path.of(System.getProperty("vandorlabs.screenArtworkReference")))){source=JsonParser.parseReader(reader).getAsJsonObject();}catch(java.io.IOException failure){throw new IllegalStateException(failure);}pairs=source.getAsJsonObject("pairs");choices=source.getAsJsonArray("choices");for(var id:source.getAsJsonArray("framed"))framed.add(id.getAsString());for(var id:source.getAsJsonArray("inputs"))inputs.add(id.getAsString());}
 public String defaultInput(){return source.getAsJsonArray("inputs").get(0).getAsString();}public boolean validInput(String value){return inputs.contains(value);}public boolean validMaterial(int value){return ModernFinishCatalog.validChoice(value);}public int material(int value){return ModernFinishCatalog.storedChoice(value);}
 public boolean legacyFramed(String id){return framed.contains(id);}public String pairedBare(String id){return pairs.has(id)?pairs.get(id).getAsString():null;}public boolean framedChoice(int value){return value>=0&&value<choices.size()&&choices.get(value).getAsJsonObject().get("framed").getAsBoolean();}public int bareChoice(int value){return value>=0&&value<choices.size()?choices.get(value).getAsJsonObject().get("bare").getAsInt():value;}public int defaultFrame(){return source.get("frame").getAsInt();}public int defaultHousing(){for(int i=0;i<ModernFinishCatalog.ENTRIES.size();i++)if(ModernFinishCatalog.ENTRIES.get(i).id().equals("door_inner"))return i;throw new IllegalStateException("Missing device housing");}public boolean validFrame(int value){return com.vandorlabs.neoforge.door.NativeDoorSettings.frame(value);}public boolean validFrameSurface(int value){return com.vandorlabs.neoforge.door.NativeDoorSettings.surface(value);}
}
